import {
  CommonPracticeObservability,
  declareCommonPracticeAxiomResources,
} from "@common-practice/infrastructure/axiom/resources";
import { sharedDatasets } from "@common-practice/infrastructure/axiom/types";
import {
  requireProductionStage,
  telemetryStackProps,
} from "@common-practice/infrastructure/stacks/telemetry";
import * as Effect from "effect/Effect";

/** Common Practice owns its dashboards and ingest token; Site continues to own the datasets. */
export default CommonPracticeObservability.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const { dashboardCount } = yield* declareCommonPracticeAxiomResources(sharedDatasets);
    return { dashboardCount };
  }),
);
import {
  CommonPracticeTraceExport,
  declareCommonPracticeTraceDestination,
  declareCommonPracticeLogDestination,
} from "@common-practice/infrastructure/cloudflare/traces";
import {
  requireProductionStage,
  telemetryStackProps,
} from "@common-practice/infrastructure/stacks/telemetry";
import * as Effect from "effect/Effect";

/** Separate state keeps dashboard updates independent of Cloudflare trace permissions. */
export default CommonPracticeTraceExport.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const destination = yield* declareCommonPracticeTraceDestination();
    const logs = yield* declareCommonPracticeLogDestination();
    // Hosted Websites read this persisted name. Never output the destination's headers.
    return { destinationName: destination.name, logsDestinationName: logs.name };
  }),
);
